/**
 * @distilled.cloud/bitbucket -- Bitbucket Cloud REST API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-bitbucket/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * Bitbucket Cloud is one service, so its operations are exported straight off
 * the package root.
 *
 * @example
 * ```ts
 * import * as Bitbucket from "@distilled.cloud/bitbucket";
 *
 * const repo = yield* Bitbucket.getRepository({ workspace: "acme", repo_slug: "api" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { BitbucketProtocol, type BitbucketOpError, type BitbucketOpContext } from "./protocol.ts";
export { paginateNextPage } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/bitbucket.ts";
// The service-local typed error classes shadow the same-named shared ones
// from ./errors.ts -- the operations raise the service-local classes.
export { BadRequest, Conflict, Forbidden, NotFound } from "./services/bitbucket.ts";
